local root = workspace:FindFirstChild("Landscape") or Instance.new("Folder")
root.Name = "Landscape"; root.Parent = workspace
local holder = root:FindFirstChild("Instances") or Instance.new("Folder")
holder.Name = "Instances"; holder.Parent = root
holder:ClearAllChildren()

local byAsset = {}
for _, e in ipairs(INSTANCES) do
	local name, bx, by, bz, yaw, s = e[1], e[2], e[3], e[4], e[5], e[6]
	local template = assetsFolder:FindFirstChild(name)
	if template then
		local folder = byAsset[name]
		if not folder then
			folder = Instance.new("Folder"); folder.Name = name; folder.Parent = holder; byAsset[name] = folder
		end
		local part = template:Clone()
		part.Anchored = true; part.CanCollide = true
		part.Size = template.Size * s
		local b = BOUNDS[name] or {0, 0}
		local centreUp = (b[1] + b[2]) / 2 * s          -- mesh pivot is its bbox centre
		local pos = Vector3.new(bx, bz + centreUp, -by)
		part.CFrame = CFrame.new(pos) * CFrame.Angles(0, math.rad(yaw), 0)
		part.Parent = folder
	else
		warn("missing asset template: " .. name)
	end
end
print("placed", #INSTANCES, "landscape instances")
